-- Seed records are idempotent so a failed migration can be safely re-run.
-- The migration never creates a human account or password. The later identity bootstrap flow must
-- create the first administrator with an operator-supplied Argon2id password.

VALUES ('01J00000000000000000000000', 'default', '默认租户', 'Asia/Shanghai', 'zh-CN', 'ACTIVE', 1, UTC_TIMESTAMP(3), UTC_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE id = id;

