SELECT '01J00000000000000000000030', id, 'ALLOW', UTC_TIMESTAMP(3)
FROM authz_permission
WHERE tenant_id = '01J00000000000000000000000' AND application_id = '01J00000000000000000000001' AND status = 'ACTIVE';

SELECT '01J00000000000000000000031', id, 'ALLOW', UTC_TIMESTAMP(3)
FROM authz_permission
WHERE application_id = '01J00000000000000000000001'
  AND code IN (
      'platform:user:read', 'platform:user:create', 'platform:user:update',
      'platform:account:read', 'platform:account:update',
      'platform:organization:read', 'platform:organization:create',
      'platform:position:read', 'platform:position:create',
      'platform:membership:read', 'platform:membership:create', 'platform:membership:update',
      'platform:resource:read', 'platform:resource:create',
      'platform:permission:read', 'platform:permission:create',
      'platform:role:read', 'platform:role:create', 'platform:role:update',
      'platform:role-binding:read', 'platform:role-binding:create', 'platform:role-binding:update',
      'platform:authorization:check'
  );

SELECT '01J00000000000000000000032', id, 'ALLOW', UTC_TIMESTAMP(3)
FROM authz_permission
WHERE application_id = '01J00000000000000000000001'
  AND code IN ('platform:audit:view', 'platform:audit:export');

VALUES ('01J00000000000000000000000', '01J00000000000000000000001', 1, UTC_TIMESTAMP(3), 'initial platform authorization seed')
ON DUPLICATE KEY UPDATE tenant_id = tenant_id;

